	{
		final String hiscoresName;
		final int varpId;

		BossVarp(String hiscoresName, int varpId)
		{
			this.hiscoresName = hiscoresName;
			this.varpId = varpId;
		}
	}
}

package com.pathscapesync;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.game.ItemManager;

/**
 * Builds a schemaVersion 1 snapshot from the logged-in local player only.
 */
final class SnapshotCollector
{
	private static final int[] CA_TASK_VARPS = {
		VarPlayerID.CA_TASK_COMPLETED_0,
		VarPlayerID.CA_TASK_COMPLETED_1,
		VarPlayerID.CA_TASK_COMPLETED_2,
		VarPlayerID.CA_TASK_COMPLETED_3,
		VarPlayerID.CA_TASK_COMPLETED_4,
		VarPlayerID.CA_TASK_COMPLETED_5,
		VarPlayerID.CA_TASK_COMPLETED_6,
		VarPlayerID.CA_TASK_COMPLETED_7,
		VarPlayerID.CA_TASK_COMPLETED_8,
		VarPlayerID.CA_TASK_COMPLETED_9,
		VarPlayerID.CA_TASK_COMPLETED_10,
		VarPlayerID.CA_TASK_COMPLETED_11,
		VarPlayerID.CA_TASK_COMPLETED_12,
		VarPlayerID.CA_TASK_COMPLETED_13,
		VarPlayerID.CA_TASK_COMPLETED_14,
		VarPlayerID.CA_TASK_COMPLETED_15,
		VarPlayerID.CA_TASK_COMPLETED_16,
		VarPlayerID.CA_TASK_COMPLETED_17,
		VarPlayerID.CA_TASK_COMPLETED_18,
		VarPlayerID.CA_TASK_COMPLETED_19,
		VarPlayerID.CA_TASK_COMPLETED_20,
	};

	private final Client client;
	private final ItemManager itemManager;

	SnapshotCollector(Client client, ItemManager itemManager)
	{
		this.client = client;
		this.itemManager = itemManager;
	}

	JsonObject collect(String rsn)
	{
		JsonObject root = new JsonObject();
		root.addProperty("schemaVersion", 1);
		root.addProperty("rsn", rsn);

		JsonArray kinds = new JsonArray();
		kinds.add("skills");
		kinds.add("quests");
		kinds.add("diaries");
		kinds.add("combatAchievements");
		kinds.add("bossKc");
		kinds.add("equipment");
		root.add("kinds", kinds);

		root.add("skills", collectSkills());
		root.add("quests", collectQuests());
		root.add("diaries", DiarySnapshot.collect(client));
		root.add("combatAchievements", collectCombatAchievements());
		root.add("bossKc", BossKillSnapshot.collect(client));
		root.add("equipment", collectEquipment());
		return root;
	}

	private JsonArray collectSkills()
	{
		JsonArray skills = new JsonArray();
		for (Skill skill : Skill.values())
		{
			if (skill == Skill.OVERALL)
			{
				continue;
			}
			JsonObject row = new JsonObject();
			row.addProperty("name", skill.getName());
			row.addProperty("level", client.getRealSkillLevel(skill));
			row.addProperty("xp", client.getSkillExperience(skill));
			skills.add(row);
		}
		return skills;
	}

	private JsonArray collectQuests()
	{
		JsonArray quests = new JsonArray();
		for (Quest quest : Quest.values())
		{
			QuestState state = quest.getState(client);
			JsonObject row = new JsonObject();
			row.addProperty("id", quest.getId());
			row.addProperty("name", quest.getName());
			row.addProperty("state", toRuneProfileState(state));
			quests.add(row);
		}
		return quests;
	}

	private JsonObject collectCombatAchievements()
	{
		JsonArray ids = new JsonArray();
		for (int varpIndex = 0; varpIndex < CA_TASK_VARPS.length; varpIndex++)
		{
			int value = client.getVarpValue(CA_TASK_VARPS[varpIndex]);
			for (int bit = 0; bit < 32; bit++)
			{
				if (((value >> bit) & 1) == 1)
				{
					ids.add(varpIndex * 32 + bit);
				}
			}
		}
		JsonObject wrap = new JsonObject();
		wrap.add("completedTaskIds", ids);
		return wrap;
	}

	private JsonObject collectEquipment()
	{
		JsonObject equipment = new JsonObject();
		ItemContainer container = client.getItemContainer(InventoryID.EQUIPMENT);
		addSlot(equipment, container, EquipmentInventorySlot.HEAD, "head");
		addSlot(equipment, container, EquipmentInventorySlot.CAPE, "cape");
		addSlot(equipment, container, EquipmentInventorySlot.AMULET, "amulet");
		addSlot(equipment, container, EquipmentInventorySlot.WEAPON, "weapon");
		addSlot(equipment, container, EquipmentInventorySlot.BODY, "body");
		addSlot(equipment, container, EquipmentInventorySlot.SHIELD, "shield");
		addSlot(equipment, container, EquipmentInventorySlot.LEGS, "legs");
		addSlot(equipment, container, EquipmentInventorySlot.GLOVES, "gloves");
		addSlot(equipment, container, EquipmentInventorySlot.BOOTS, "boots");
		addSlot(equipment, container, EquipmentInventorySlot.RING, "ring");
		addSlot(equipment, container, EquipmentInventorySlot.AMMO, "ammo");
		return equipment;
	}

	private void addSlot(JsonObject equipment, ItemContainer container, EquipmentInventorySlot slot, String id)
	{
		if (container == null)
		{
			return;
		}
		Item item = container.getItem(slot.getSlotIdx());
		if (item == null || item.getId() <= 0)
		{
			return;
		}
		JsonObject row = new JsonObject();
		row.addProperty("id", item.getId());
		row.addProperty("name", itemManager.getItemComposition(item.getId()).getName());
		row.addProperty("quantity", item.getQuantity());
		equipment.add(id, row);
	}

	private static String toRuneProfileState(QuestState state)
	{
		if (state == QuestState.FINISHED)
		{
			return "finished";
		}
		if (state == QuestState.IN_PROGRESS)
		{
			return "in_progress";
		}
		return "not_started";
	}
}

package com.pathscapesync;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(PathScapeSyncConfig.GROUP)
public interface PathScapeSyncConfig extends Config
{
	String GROUP = "pathscape-sync";

	@ConfigSection(
		name = "Link",
		description = "Paste the link token and public API key from PathScape Preferences, then hit Pair in the side panel.",
		position = 0
	)
	String linkSection = "linkSection";

	@ConfigSection(
		name = "Upload",
		description = "When and how often snapshots are sent.",
		position = 1
	)
	String uploadSection = "uploadSection";

	@ConfigItem(
		keyName = "submitToPathscape",
		name = "Submit to PathScape",
		description = "Send this logged-in account's skills, quests, diaries, combat achievements, boss KC, and worn gear to PathScape.",
		warning = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers",
		section = uploadSection,
		position = 0
	)
	default boolean submitToPathscape()
	{
		return false;
	}

	@ConfigItem(
		keyName = "linkToken",
		name = "Link token",
		description = "64-character token from PathScape Preferences → PathScape Sync. Paste it here, then hit Pair.",
		section = linkSection,
		secret = true,
		position = 1
	)
	default String linkToken()
	{
		return "";
	}

	/**
	 * Legacy short pairing code (cloud email flow). Still accepted if link token is empty.
	 */
	@ConfigItem(
		keyName = "pairingCode",
		name = "Legacy pairing code",
		description = "Old short code from signed-in Preferences. Prefer Link token above for new setups.",
		section = linkSection,
		secret = true,
		position = 2
	)
	default String pairingCode()
	{
		return "";
	}

	@ConfigItem(
		keyName = "publicApiKey",
		name = "PathScape public API key",
		description = "The public anon key shown in PathScape Preferences. The gateway may require it; it is not a password.",
		section = linkSection,
		secret = true,
		position = 3
	)
	default String publicApiKey()
	{
		return "";
	}

	@ConfigItem(
		keyName = "uploadInterval",
		name = "Upload interval",
		description = "How often to post a snapshot after the login snapshot.",
		section = uploadSection,
		position = 1
	)
	default UploadInterval uploadInterval()
	{
		return UploadInterval.FIVE_MINUTES;
	}

	@ConfigItem(
		keyName = "status",
		name = "Status",
		description = "Last Pair or Sync result. Also shown in the PathScape Sync side panel.",
		section = linkSection,
		position = 4
	)
	default String status()
	{
		return "Not linked";
	}
}

package com.pathscapesync;

/**
 * How often a full snapshot is posted after the login snapshot.
 */
public enum UploadInterval
{
	ONE_MINUTE(1),
	FIVE_MINUTES(5),
	TEN_MINUTES(10),
	SIXTY_MINUTES(60);

	private final int minutes;

	UploadInterval(int minutes)
	{
		this.minutes = minutes;
	}

	public int getMinutes()
	{
		return minutes;
	}

	@Override
	public String toString()
	{
		return minutes == 1 ? "1 minute" : minutes + " minutes";
	}
}

package com.pathscapesync;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.InventoryID;
import net.runelite.api.Player;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import okhttp3.OkHttpClient;

@Slf4j
@PluginDescriptor(
	name = "PathScape Sync"
)
public class PathScapeSyncPlugin extends Plugin
{
	private static final String DEVICE_TOKEN_KEY = "deviceToken";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private PathScapeSyncConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private OkHttpClient okHttpClient;

	@Inject
	private Gson gson;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ClientToolbar clientToolbar;

	private PathScapeSyncClient syncClient;
	private SnapshotCollector collector;
	private PathScapeSyncPanel panel;
	private NavigationButton navButton;
	private ScheduledFuture<?> uploadTask;
	private ScheduledFuture<?> equipmentDebounce;

	@Override
	protected void startUp()
	{
		syncClient = new PathScapeSyncClient(okHttpClient, gson);
		collector = new SnapshotCollector(client, itemManager);
		panel = new PathScapeSyncPanel(this::onPairClicked, this::onSyncClicked);
		panel.setStatus(config.status());

		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("PathScape Sync")
			.icon(icon)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		log.info("PathScape Sync started");
		rescheduleUploads();
	}

	@Override
	protected void shutDown()
	{
		cancelUploads();
		cancelEquipmentDebounce();
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		panel = null;
		log.info("PathScape Sync stopped");
	}

	@Provides
	PathScapeSyncConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PathScapeSyncConfig.class);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invokeLater(this::onLoggedIn);
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!PathScapeSyncConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		if (DEVICE_TOKEN_KEY.equals(event.getKey()) || "status".equals(event.getKey()))
		{
			return;
		}
		// Pairing is manual from the side panel. Config changes only retune the interval timer.
		rescheduleUploads();
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (!config.submitToPathscape() || getDeviceToken() == null)
		{
			return;
		}
		if (event.getContainerId() != InventoryID.EQUIPMENT.getId())
		{
			return;
		}
		cancelEquipmentDebounce();
		equipmentDebounce = executor.schedule(
			() -> clientThread.invoke(() -> uploadSnapshot(false)),
			2,
			TimeUnit.SECONDS
		);
	}

	/**
	 * Pair is a button in the side panel, not automatic on login or config change.
	 */
	void onPairClicked()
	{
		setStatus("Pairing\u2026");
		clientThread.invoke(this::pairNow);
	}

	/**
	 * One snapshot, now. Does not pair. Submit must already be on.
	 */
	void onSyncClicked()
	{
		setStatus("Uploading\u2026");
		clientThread.invoke(this::syncNow);
	}

	private void onLoggedIn()
	{
		if (!config.submitToPathscape() || getDeviceToken() == null)
		{
			return;
		}
		uploadSnapshot(false);
	}

	private void pairNow()
	{
		Player local = client.getLocalPlayer();
		if (local == null || local.getName() == null)
		{
			fail("Log in to Old School RuneScape first");
			return;
		}
		String linkToken = config.linkToken() == null ? "" : config.linkToken().trim();
		String legacyCode = config.pairingCode() == null ? "" : config.pairingCode().trim();
		String codeOrToken = !linkToken.isEmpty() ? linkToken : legacyCode;
		if (codeOrToken.isEmpty())
		{
			fail("Paste a link token from PathScape Preferences");
			return;
		}
		String apiKey = publicApiKey();
		if (apiKey.isEmpty())
		{
			fail("Paste the PathScape public API key");
			return;
		}

		String rsn = local.getName();
		syncClient.pair(apiKey, codeOrToken, rsn, result -> clientThread.invoke(() ->
		{
			if (!result.ok)
			{
				fail(result.error != null ? result.error : "Pairing failed");
				return;
			}
			storeDeviceToken(result.token);
			setStatus("Linked as " + rsn);
			chat("PathScape Sync linked as " + rsn + ".");
		}));
	}

	private void syncNow()
	{
		if (!config.submitToPathscape())
		{
			fail("Enable Submit to PathScape first");
			return;
		}
		if (getDeviceToken() == null)
		{
			fail("Pair this client first");
			return;
		}
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			fail("Log in to Old School RuneScape first");
			return;
		}
		uploadSnapshot(true);
	}

	private void uploadSnapshot(boolean announce)
	{
		if (!config.submitToPathscape())
		{
			return;
		}
		String token = getDeviceToken();
		if (token == null)
		{
			return;
		}
		Player local = client.getLocalPlayer();
		if (local == null || local.getName() == null)
		{
			if (announce)
			{
				fail("Log in to Old School RuneScape first");
			}
			return;
		}
		String rsn = local.getName();
		JsonObject payload = collector.collect(rsn);
		syncClient.postSnapshot(publicApiKey(), token, payload, error -> clientThread.invoke(() ->
		{
			if (error != null)
			{
				setStatus("Upload failed: " + error);
				log.debug("PathScape snapshot failed: {}", error);
				if (announce)
				{
					chat("PathScape Sync: " + error);
				}
				return;
			}
			setStatus("Uploaded " + rsn);
			log.debug("PathScape snapshot posted for {}", rsn);
			if (announce)
			{
				chat("PathScape snapshot uploaded.");
			}
		}));
	}

	private void rescheduleUploads()
	{
		cancelUploads();
		if (!config.submitToPathscape())
		{
			return;
		}
		int minutes = config.uploadInterval().getMinutes();
		uploadTask = executor.scheduleAtFixedRate(
			() -> clientThread.invoke(() -> uploadSnapshot(false)),
			minutes,
			minutes,
			TimeUnit.MINUTES
		);
	}

	private void cancelUploads()
	{
		if (uploadTask != null)
		{
			uploadTask.cancel(false);
			uploadTask = null;
		}
	}

	private void cancelEquipmentDebounce()
	{
		if (equipmentDebounce != null)
		{
			equipmentDebounce.cancel(false);
			equipmentDebounce = null;
		}
	}

	private String publicApiKey()
	{
		String key = config.publicApiKey();
		return key == null ? "" : key.trim();
	}

	private String getDeviceToken()
	{
		String token = configManager.getRSProfileConfiguration(PathScapeSyncConfig.GROUP, DEVICE_TOKEN_KEY);
		if (token == null || token.trim().isEmpty())
		{
			return null;
		}
		return token.trim();
	}

	private void storeDeviceToken(String token)
	{
		configManager.setRSProfileConfiguration(PathScapeSyncConfig.GROUP, DEVICE_TOKEN_KEY, token);
	}

	private void fail(String message)
	{
		setStatus(message);
		chat("PathScape Sync: " + message);
	}

	private void chat(String message)
	{
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
	}

	private void setStatus(String status)
	{
		configManager.setConfiguration(PathScapeSyncConfig.GROUP, "status", status);
		PathScapeSyncPanel current = panel;
		if (current != null)
		{
			SwingUtilities.invokeLater(() -> current.setStatus(status));
		}
	}
}

package com.pathscapesync;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * HTTPS client for the PathScape ingest Edge Function. Never talks to Postgres.
 */
@Slf4j
final class PathScapeSyncClient
{
	static final String INGEST_URL = "https://eczmozhetrhgdlesbkqp.supabase.co/functions/v1/pathscape-sync";

	private static final MediaType JSON = MediaType.get("application/json; charset=utf-8");
	private static final int MAX_BODY_CHARS = 4096;

	private final OkHttpClient http;
	private final Gson gson;

	PathScapeSyncClient(OkHttpClient http, Gson gson)
	{
		this.http = http;
		this.gson = gson;
	}

	void pair(String apiKey, String codeOrToken, String claimedRsn, Consumer<PairResult> callback)
	{
		JsonObject body = new JsonObject();
		body.addProperty("action", "pair");
		// Link tokens are 64 hex chars; legacy codes are short uppercase. Edge Function routes both.
		String trimmed = codeOrToken == null ? "" : codeOrToken.trim();
		if (trimmed.matches("(?i)[0-9a-f]{64}"))
		{
			body.addProperty("token", trimmed.toLowerCase());
			body.addProperty("code", trimmed.toLowerCase());
		}
		else
		{
			body.addProperty("code", trimmed.toUpperCase());
		}
		body.addProperty("claimedRsn", claimedRsn);
		enqueue(apiKey, null, body, (ok, json, error) ->
		{
			if (!ok)
			{
				callback.accept(PairResult.fail(error));
				return;
			}
			String token = json.has("token") && !json.get("token").isJsonNull()
				? json.get("token").getAsString()
				: "";
			if (token.isEmpty())
			{
				callback.accept(PairResult.fail("Pairing response had no token"));
				return;
			}
			callback.accept(PairResult.ok(token));
		});
	}

	void postSnapshot(String apiKey, String deviceToken, JsonObject payload, Consumer<String> errorOrNull)
	{
		payload.addProperty("action", "snapshot");
		enqueue(apiKey, deviceToken, payload, (ok, json, error) ->
		{
			if (!ok)
			{
				errorOrNull.accept(error);
				return;
			}
			errorOrNull.accept(null);
		});
	}

	private void enqueue(String apiKey, String deviceToken, JsonObject body, ResponseHandler handler)
	{
		String json = gson.toJson(body);
		Request.Builder builder = new Request.Builder()
			.url(INGEST_URL)
			.post(RequestBody.create(JSON, json))
			.header("Content-Type", "application/json");

		if (apiKey != null && !apiKey.isEmpty())
		{
			builder.header("apikey", apiKey);
		}

		// Gateway often wants a JWT-shaped Authorization; the device token is the real proof.
		if (deviceToken != null && !deviceToken.isEmpty())
		{
			builder.header("Authorization", "Bearer " + (apiKey != null && !apiKey.isEmpty() ? apiKey : deviceToken));
			builder.header("X-Pathscape-Token", deviceToken);
		}
		else if (apiKey != null && !apiKey.isEmpty())
		{
			builder.header("Authorization", "Bearer " + apiKey);
		}

		http.newCall(builder.build()).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("PathScape Sync request failed: {}", e.toString());
				handler.handle(false, null, e.getMessage() != null ? e.getMessage() : "Network error");
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody responseBody = response.body())
				{
					String text = responseBody != null ? responseBody.string() : "";
					if (text.length() > MAX_BODY_CHARS)
					{
						text = text.substring(0, MAX_BODY_CHARS);
					}
					JsonObject parsed = parseObject(gson, text);
					if (!response.isSuccessful())
					{
						String error = messageFrom(parsed, "HTTP " + response.code());
						log.debug("PathScape Sync HTTP {}: {}", response.code(), error);
						handler.handle(false, parsed, error);
						return;
					}
					handler.handle(true, parsed, null);
				}
				catch (IOException e)
				{
					handler.handle(false, null, e.getMessage() != null ? e.getMessage() : "Read error");
				}
			}
		});
	}

	private static JsonObject parseObject(Gson gson, String text)
	{
		if (text == null || text.isEmpty())
		{
			return new JsonObject();
		}
		try
		{
			JsonObject parsed = gson.fromJson(text, JsonObject.class);
			return parsed != null ? parsed : new JsonObject();
		}
		catch (RuntimeException e)
		{
			return new JsonObject();
		}
	}

	private static String messageFrom(JsonObject json, String fallback)
	{
		if (json.has("error") && !json.get("error").isJsonNull())
		{
			return json.get("error").getAsString();
		}
		return fallback;
	}

	interface ResponseHandler
	{
		void handle(boolean ok, JsonObject json, String error);
	}

	static final class PairResult
	{
		final boolean ok;
		final String token;
		final String error;

		private PairResult(boolean ok, String token, String error)
		{
			this.ok = ok;
			this.token = token;
			this.error = error;
		}

		static PairResult ok(String token)
		{
			return new PairResult(true, token, null);
		}

		static PairResult fail(String error)
		{
			return new PairResult(false, null, error);
		}
	}
}

